@spec tuning_spec  src=tests/specs/tuning_spec.lua  loc=510  cases=36
@exercises tuning (tuning)
@surface   tuning.derive, tuning.stepToParts, tuning.midiToStep, tuning.scalaPitch, tuning.stepToMidi, tuning.parseScalaFile, tuning.parseScalaPitches, tuning.scalaToTemper, tuning.genEqual, tuning.edoDegrees, tuning.degreesToSpec, tuning.genHarmonics, tuning.genSubharmonics, tuning.parseChord, tuning.genChord, tuning.genCPS, tuning.genRank2, tuning.nextMosSize, tuning.mosInfo

# Intent
  Pins tuning.lua's pure display + derivation layer: the Option-B nameless
  step labels, the derived octaveStep / cellWidth fields, and the coordinate
  conversions between MIDI and step-octave. Realisation invariants (I1-I5)
  live in tm_tuning_spec; projection wiring in view_context_spec.

# Helpers
  @fn nameless(cents)  @ 9-11
  @fn stepText(temper, step, octave)  @ 15-18
      -- The two label parts joined, so a case that is about the whole label can
      -- assert it as one string.
  @fn rooted(root)  @ 21-27
      -- A 12EDO scale with the root fields the case is about; everything else default.

# Cases
  @case 'preset EDOs derive width 3 and a past-the-end octaveStep'  [pure]  @ 31-41
  @case 'named step renders name + octave'  [pure]  @ 45-50
  @case 'a negative octave renders as its magnitude and reports the sign'  [pure]  @ 54-63
  @case 'the octaveStep bump owns the sign: a step that crosses zero is not negative'  [pure]  @ 67-74
  @case 'nameless step falls back to degree-octave with a dash'  [pure]  @ 78-86
  @case 'nameless scale past 9 steps widens the cell for 2-digit degrees'  [pure]  @ 90-97
  @case 'sub-octave period widens the octave field for 2-digit octaves'  [pure]  @ 101-110
  @case 'a root numbering the octaves near zero narrows the field'  [pure]  @ 114-134
  @case 'a root numbering the range low makes the bottom end the wider'  [pure]  @ 138-150
  @case 'derive recomputes width when names are dropped'  [pure]  @ 154-162
  @case 'partially named scale: named steps keep their label, blanks fall back'  [pure]  @ 166-173
  @case 'scalaPitch parses ratios, cents, bare integers and n\\m steps'  [pure]  @ 177-191
  @case 'derive compiles pitches → cents and periodPitch → period'  [pure]  @ 195-203
  @case 'derive reduces an authored root to rootCents + octaveBase'  [pure]  @ 207-217
  @case 'a preset states no root and derives the default (0,0) = (1,-1)'  [pure]  @ 221-230
  @case 'the default root reduces the conversions to MIDI-relative arithmetic'  [pure]  @ 234-249
  @case 'a flattened root moves every pitch by its offset and renames nothing'  [pure]  @ 253-275
  @case 'an octave-shifted root renames every octave and moves no pitch'  [pure]  @ 279-295
  @case 'the conversions invert each other at every root'  [pure]  @ 299-312
  @case 'EDO presets carry n\\m source tokens that derive back to their cents'  [pure]  @ 316-323
  @case 'parseScalaFile strips comments, description and count; returns pitch tokens'  [pure]  @ 327-335
  @case 'parseScalaPitches keeps every non-comment, non-blank line'  [pure]  @ 339-344
  @case 'scalaToTemper prepends the unison, splits the period, flags periodAsStep'  [pure]  @ 348-359
  @case 'scalaToTemper sorts unordered pitches ascending; widest becomes the period'  [pure]  @ 363-372
  @case 'scalaToTemper rejects an unparseable token'  [pure]  @ 376-381
  @case 'genEqual: full EDO and a diatonic subset, base implicit, period last'  [pure]  @ 385-397
  @case 'edoDegrees: relative cumulates, absolute sorts; non-octave equave suffixes'  [pure]  @ 401-409
  @case 'degreesToSpec round-trips edoDegrees in both modes'  [pure]  @ 413-417
  @case 'genHarmonics / genSubharmonics: rooted on the low harmonic, top is period'  [pure]  @ 421-430
  @case 'genChord: otonal vs inverted, last member is the period'  [pure]  @ 434-446
  @case 'parseChord rejects fewer than two notes or non-integers'  [pure]  @ 450-454
  @case 'genCPS: hexany rooted on the smallest product, 1/1 first, ascending'  [pure]  @ 458-464
  @case 'genRank2: pure-fifth size 7 / up 5 is Pythagorean major, 1/1 first'  [pure]  @ 468-474
  @case 'genRank2: size 4 / up 2 matches the Scale Workshop worked example'  [pure]  @ 478-483
  @case 'genRank2: irrational (EDO-step) generator emits cents tokens'  [pure]  @ 487-492
  @case 'nextMosSize / mosInfo: pure-fifth ladder 2->3->5->7->12; 7 is 5L 2s'  [pure]  @ 496-508

